class VoxRecorder extends AudioWorkletProcessor {
  constructor() {
    super()
    this.on = false
    this.buf = new Float32Array(4096)
    this.n = 0
    this.start = 0
    this.port.onmessage = (e) => {
      if (e.data === 'on') { this.on = true; this.n = 0 }
      else if (e.data === 'off') { this.flush(); this.on = false; this.port.postMessage({ done: true }) }
    }
  }
  flush() {
    if (this.n) { this.port.postMessage({ frame: this.start, data: this.buf.slice(0, this.n) }); this.n = 0 }
  }
  process(inputs) {
    const ch = inputs[0]
    if (this.on && ch && ch.length) {
      const len = ch[0].length
      if (this.n + len > this.buf.length) this.flush()
      if (this.n === 0) this.start = currentFrame
      for (let i = 0; i < len; i++) {
        let v = 0
        for (let c = 0; c < ch.length; c++) v += ch[c][i]
        this.buf[this.n++] = v / ch.length
      }
    }
    return true
  }
}
